#!/usr/bin/env python3
"""Generate Arabic C1 Unit 04: language, identity, and society with fictional sociolinguistic cases."""
from __future__ import annotations
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'reading/arabic/c1/passages.jsonl';LEX=ROOT/'reading/lexicons/arabic.jsonl'
AR_DIAC=re.compile(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]')
def norm(s):return AR_DIAC.sub('',unicodedata.normalize('NFC',str(s or '')).replace('ـ','').strip())
def lexicon():
 d={}
 for line in LEX.read_text(encoding='utf-8').splitlines():
  if line.strip():
   r=json.loads(line);d.setdefault(norm(r.get('form','')),r)
 return d
def row(f,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f'cleared lexicon form missing: {f}')
 return r
SENSE={'مصطلح':'term; technical expression','قاموس':'dictionary; lexicon','تنوع':'diversity; variety','تعايش':'coexistence','نوعية':'quality; type or character','أوسع':'wider; broader','سمعي':'auditory; spoken/audio-related','نثر':'prose','تطبيع':'normalization; making a form conventional','معاصر':'contemporary'}
def target(f,text,d):
 r=row(f,d);return {'id':f"ar-r{r['rank']}",'form':f,'lemma':f,'part_of_speech':r.get('part_of_speech_source'),'intended_sense':SENSE[f],'register':'sociolinguistic/contemporary standard','variety':'MSA','context_strategy':['language_variation','audience_register','identity_interpretation'],'first_introduced':True,'exposures_in_text':max(1,text.count(f)),'source_lexicon':r.get('source_file'),'source_rank':r['rank'],'beyond_base':False}
def review(f,s,rep,d):
 r=row(f,d);return {'id':f"ar-r{r['rank']}",'form':f,'review_stage':s,'representation':rep}
def qa(items,ids):
 q=[];a=[]
 for i,(typ,p,ans,f) in enumerate(items,1):
  z={'id':f'q{i}','type':typ,'prompt':p,'answer_id':f'a{i}'}
  if f:z['target_ids']=[ids[f]]
  q.append(z);a.append({'id':f'a{i}','question_id':f'q{i}','answer':ans,'explanation':''})
 if len(q)!=10:raise ValueError('ten questions required')
 return q,a
